INSERT INTO projets (id, slug, titre, titre_accent, secteur, client, periode, montant, resume, description, resultats, photo_url, statut, ordre_affichage) VALUES ('gouvernance-pev-lmc', 'gouvernance-pev-lmc', 'Gouvernance du Programme Élargi de Vaccination (LMC)', 'Vaccination', 'sante', 'Gavi · MSHP', 'Mars 2024 – Oct. 2025', NULL, '8 régions administratives appuyées, 150+ acteurs formés et un tableau de bord digitalisé déployé au niveau national.', 'Le Projet LMC (Leadership, Management et Coordination du PEV) vise à renforcer la gouvernance vaccinale en Guinée. Diagnostic institutionnel, cartographie des ressources humaines, plan de formation pour plus de 150 acteurs et mise en place de tableaux de bord digitaux dans les 8 régions administratives.', '["8 régions administratives appuyées","150+ acteurs du PEV formés","10 outils standardisés développés et adoptés","1 tableau de bord digitalisé opérationnel"]', '/img/realisations/gavi-mshp.jpg', 'publie', 0);
INSERT INTO projets (id, slug, titre, titre_accent, secteur, client, periode, montant, resume, description, resultats, photo_url, statut, ordre_affichage) VALUES ('evaluation-rh-pev', 'evaluation-rh-pev', 'Évaluation des ressources humaines du PEV', 'ressources humaines', 'sante', 'Gavi · MSHP', 'Sept. – Nov. 2025', NULL, 'État des lieux complet des effectifs et compétences du PEV, assorti d''un plan de renforcement RH validé par le ministère.', 'État des lieux complet des ressources humaines du PEV, incluant la cartographie des profils, l''analyse des compétences et la définition d''un plan de renforcement, pour mieux planifier et motiver les équipes.', '["Rapport RH validé par le PEV","Base de données RH consolidée (≥95 %)","Plan de renforcement des compétences adopté"]', '/img/realisations/eval-rh-pev.png', 'publie', 1);
INSERT INTO projets (id, slug, titre, titre_accent, secteur, client, periode, montant, resume, description, resultats, photo_url, statut, ordre_affichage) VALUES ('outils-digitaux-pev', 'outils-digitaux-pev', 'Outils de gestion digitaux du PEV', 'digitaux', 'ia', 'Gavi · MSHP', 'Sept. – Déc. 2025', NULL, 'Deux plateformes numériques : gestion RH/formation avec e-learning et chatbot, et gestion des partenaires techniques.', 'Deux outils numériques structurants : une plateforme de gestion RH et de formation (suivi du personnel, e-learning, chatbot, certificats), et une plateforme de gestion des partenaires techniques avec cartographie dynamique des acteurs.', '["Plateforme RH fonctionnelle avec module e-learning","Base de données RH suivie en temps réel","Cartographie dynamique des partenaires"]', '/img/realisations/outils-digitaux-pev.png', 'publie', 2);
INSERT INTO projets (id, slug, titre, titre_accent, secteur, client, periode, montant, resume, description, resultats, photo_url, statut, ordre_affichage) VALUES ('chaine-froid-pev', 'chaine-froid-pev', 'Digitalisation de la chaîne de froid du PEV', 'chaîne de froid', 'sante', 'UNICEF · Gavi', 'Mai – Juil. 2024', NULL, '29 procédures standardisées et une cartographie interactive nationale des équipements vaccinaux.', 'Digitalisation du suivi des équipements de la chaîne du froid (ECF) : registre électronique centralisé, cartographie dynamique nationale, procédures opérationnelles standardisées et plan de maintenance révisé.', '["Registre électronique national de suivi des ECF","29 SOP validées et alignées sur les standards internationaux","Cartographie interactive couvrant tout le pays","50+ agents formés"]', '/img/realisations/unicef-mshp.jpg', 'publie', 3);
INSERT INTO projets (id, slug, titre, titre_accent, secteur, client, periode, montant, resume, description, resultats, photo_url, statut, ordre_affichage) VALUES ('cartographie-nutrition-eu4sun', 'cartographie-nutrition-eu4sun', 'Cartographie nationale de la nutrition (EU4SUN)', 'nutrition', 'sante', 'Expertise France', 'Sept. – Déc. 2024', NULL, 'Une plateforme interactive pour coordonner les acteurs et interventions en nutrition à l’échelle du pays.', 'Le projet EU4SUN dote la Guinée d''une plateforme nationale de cartographie numérique recensant les acteurs et interventions en nutrition, pour renforcer la coordination multisectorielle et l''allocation des ressources.', '["Base de données nationale des interventions et acteurs","Formulaire structuré et validé","Alignement sur les standards de qualité INS/PNLP"]', '/img/realisations/ue-expertise-france.jpg', 'publie', 4);
INSERT INTO projets (id, slug, titre, titre_accent, secteur, client, periode, montant, resume, description, resultats, photo_url, statut, ordre_affichage) VALUES ('ia-generative-pev', 'ia-generative-pev', 'IA générative pour le PEV', 'générative', 'ia', 'Gavi · MSHP', 'Sept. – Nov. 2025', NULL, 'Agent virtuel IA sécurisé pour automatiser la production documentaire : gain de temps ≥50 % et satisfaction ≥80 %.', 'Développement d''un agent virtuel d''IA générative pour automatiser la production documentaire du PEV (plans de travail, TDR, notes techniques, rapports), sécurisé, multilingue et intégré durablement dans les routines de travail.', '["Gain de temps ≥ 50 % sur la rédaction documentaire","Satisfaction ≥ 80 % des utilisateurs","15–20 référents IA santé formés"]', '/img/realisations/ia-generative-pev.png', 'publie', 5);
INSERT INTO projets (id, slug, titre, titre_accent, secteur, client, periode, montant, resume, description, resultats, photo_url, statut, ordre_affichage) VALUES ('agents-ia-osc', 'agents-ia-osc', 'Agents IA pour 10 organisations de la société civile', 'société civile', 'ia', 'Institut Français de Guinée', 'Fév. – Sept. 2025', NULL, 'Déploiement d''agents virtuels et 6 mois d''accompagnement pour l''autonomie numérique des OSC.', 'Dotation de 10 organisations de la société civile guinéennes d''agents virtuels personnalisés basés sur l''IA, avec formation pratique et accompagnement sur 6 mois pour garantir l''appropriation durable.', '["10 agents virtuels développés, testés et déployés","10 OSC accompagnées avec un usage quotidien opérationnel","Dispositif de suivi mis en place (rapports semestriels)"]', '/img/realisations/institut-francais.jpg', 'publie', 6);
INSERT INTO projets (id, slug, titre, titre_accent, secteur, client, periode, montant, resume, description, resultats, photo_url, statut, ordre_affichage) VALUES ('station-ia', 'station-ia', 'Station IA', 'IA', 'ia', 'Institut Français de Guinée', 'Sept. 2025 – Août 2026', NULL, 'Animation d''un espace dédié à la formation, l''expérimentation et l''accompagnement des usages responsables de l''IA à Conakry.', 'La Station IA est un espace dédié à l''innovation numérique et à la diffusion des usages de l''intelligence artificielle en Guinée, un lieu de formation, d''expérimentation et d''accompagnement des porteurs de projets.', '["Espace fonctionnel et attractif pour l’IA à Conakry","Centaines de bénéficiaires formés (étudiants, OSC, administrations)","Écosystème local autour de l’IA en développement"]', '/img/realisations/station-ia.png', 'publie', 7);
INSERT INTO projets (id, slug, titre, titre_accent, secteur, client, periode, montant, resume, description, resultats, photo_url, statut, ordre_affichage) VALUES ('formation-ia-rtg', 'formation-ia-rtg', 'Formation IA des cadres de la RTG', 'IA', 'ia', 'RTG', '25 juin 2025 · 1 jour', NULL, 'Journée de formation pour ~30 professionnels de l''audiovisuel aux usages concrets de l''IA.', 'Journée de formation réunissant ~30 professionnels des médias (journalistes, réalisateurs, monteurs) pour découvrir des usages concrets de l''IA dans l''audiovisuel et intégrer les enjeux éthiques.', '["30 professionnels formés","Outils pris en main : ChatGPT, Whisper, DALL·E, ElevenLabs, Canva IA","Contenus pilotes produits en séance"]', '/img/realisations/formation-ia-rtg.png', 'publie', 8);
INSERT INTO projets (id, slug, titre, titre_accent, secteur, client, periode, montant, resume, description, resultats, photo_url, statut, ordre_affichage) VALUES ('formation-ia-journalistes', 'formation-ia-journalistes', 'Formation IA pour les journalistes guinéens', 'journalistes', 'ia', 'AGUIPEL · Maison de la Presse', '5 – 6 mai 2025', NULL, 'Atelier national de 2 jours pour 60 journalistes : usages concrets de l''IA en rédaction et culture éthique.', 'À l''occasion de la Journée mondiale de la liberté de la presse, atelier national de 2 jours destiné à 60 journalistes pour l''acculturation aux usages de l''IA dans les rédactions et l''intégration d''une culture éthique.', '["60 journalistes formés","Outils pris en main : ChatGPT, DALL·E, Perplexity, Whisper","Premières lignes directrices pour un usage responsable de l’IA"]', '/img/realisations/formation-ia-journalistes.png', 'publie', 9);
INSERT INTO projets (id, slug, titre, titre_accent, secteur, client, periode, montant, resume, description, resultats, photo_url, statut, ordre_affichage) VALUES ('sommet-stein-ukag', 'sommet-stein-ukag', 'Conférencier, Sommet STEIN 2025', 'STEIN', 'education', 'Université Kofi Annan', 'Fév. – Avr. 2025', NULL, 'Formation pratique IA pour enseignants et étudiants, puis conférence plénière au Sommet STEIN 2025.', 'Formation pratique IA pour étudiants et enseignants de l''UKAG, suivie d''une intervention au Sommet STEIN 2025 (conférence plénière, atelier de haut niveau, panel) pour positionner l''université comme acteur de l''innovation numérique.', '["~20 participants formés en février 2025","Conférence plénière animée au Sommet STEIN","Recommandations pour l’intégration de l’IA dans les curricula"]', '/img/realisations/sommet-stein.png', 'publie', 10);
